                key = action.get("key")
                value = action.get("value")
                if key in table:
                    table[key] = value
                    if conn == "other":
                        other_changes += 1
                    else:
                        main_changes += 1
            elif op == "delete":
                key = action.get("key")
                if key in table:
                    del table[key]
                    if conn == "other":
                        other_changes += 1
                    else:
                        main_changes += 1
        return main, other, main_changes, other_changes

    def committed_state(actions):
        main = {}
        other = {}
        main_tx = False
        other_tx = False
        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            if conn == "other":
                table = other
                in_tx = other_tx
            else:
                table = main
                in_tx = main_tx
            if op == "begin":
