def investigate(context, acquire):
    history = acquire("history")
    receipts = []
    for h in history:
        if isinstance(h, dict):
            receipts.append(h)
    def simulate(actions, put_mode, channel_mode, trigger):
        main = {}
        other = {}
        main_changes = 0
        other_changes = 0
        main_tx = False
        other_tx = False
        main_pending = None
        other_pending = None
        def apply(conn, op, key, value):
            nonlocal main_changes, other_changes
            if conn == "main":
                table = main
                pending = main_pending
            else:
                table = other
                pending = other_pending
            if op == "put":
                if key in table:
                    if put_mode == "ignore":
                        return 0
                    if put_mode == "replace":
                        table[key] = value
                        return 1
                    if put_mode == "upsert":
                        table[key] = value
                        return 1
                else:
                    table[key] = value
                    return 1
            if op == "update":
                if key in table:
                    table[key] = value
                    return 1
                return 0
            if op == "delete":
                if key in table:
                    del table[key]
                    return 1
                return 0
            return 0
        for a in actions:
            op = a.get("op")
            conn = a.get("connection", "main")
            key = a.get("key")
            value = a.get("value")
            if op == "begin":
                if conn == "main":
                    main_tx = True
                    main_pending = dict(main)
                else:
                    other_tx = True
                    other_pending = dict(other)
            elif op == "commit":
                if conn == "main":
                    main_tx = False
                    main_pending = None
                else:
                    other_tx = False
                    other_pending = None
            elif op == "rollback":
                if conn == "main":
                    if main_pending is not None:
                        main.clear()
                        main.update(main_pending)
                    main_tx = False
                    main_pending = None
                else:
                    if other_pending is not None:
                        other.clear()
                        other.update(other_pending)
                    other_tx = False
                    other_pending = None
            else:
                if conn == "main":
                    if main_tx:
                        table = main_pending
                    else:
                        table = main
                else:
                    if other_tx:
                        table = other_pending
                    else:
                        table = other
                if op == "put":
                    if key in table:
                        if put_mode == "ignore":
                            n = 0
                        else:
                            table[key] = value
                            n = 1
                    else:
                        table[key] = value
                        n = 1
                elif op == "update":
                    if key in table:
                        table[key] = value
                        n = 1
                    else:
                        n = 0
                elif op == "delete":
                    if key in table:
                        del table[key]
                        n = 1
                    else:
                        n = 0
                else:
                    n = 0
                if conn == "main":
                    main_changes += n
                else:
                    other_changes += n
        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total_main":
            channel = main_changes
        else:
            channel = main_changes + other_changes
        if trigger:
            channel += 1
        count = len(main)
        total = 0
        for v in main.values():
            total += v
        return channel, count, total
    def consistent(put_mode, channel_mode, trigger):
        for h in receipts:
            actions = h.get("actions", [])
            obs = h.get("observed", {})
            ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
            if ch != obs.get("channel"):
                return False
            if cnt != obs.get("committed_count"):
                return False
            if sm != obs.get("committed_sum"):
                return False
        return True
